<!-- Why IndySoft Section -->
<section class="advantages-section position-relative pt-5 w-100 d-flex justify-content-center" style="background: rgba(7, 112, 252, 0.07);">
  <div class="container py-md-4" style="max-width:1500px;">
    
    <!-- Section Header -->
    <div class="row">
      <div class="col-12 text-center">
        <h2 class="m-0 mb-3 mb-md-4" style="font-family:'elza',sans-serif;font-weight:600;font-size:60px;line-height:1;color:#003040;letter-spacing:-1.8px;">Why IndySoft?</h2>
        <div class="row justify-content-center">
          <div class="col-12 col-md-10 col-lg-8" style="max-width:638px;">
            <p class="m-0 " style="font-family:'elza',sans-serif;font-weight:400;font-size:16px;line-height:1.4;color:#1C5263;">When it comes to calibration management, the details make the difference. With IndySoft, you always know exactly where you — and your instruments — stand.</p>
          </div>
        </div>
      </div>
    </div>

    <!-- Features List -->
    <div class="row d-none">
      <div class="col-12 col-lg-6">
        <!-- Feature List Items -->
        <div class="features-list" style="max-width:740px;">
          
          <!-- Feature 1 -->
          <div class="d-flex gap-4 align-items-start" style="padding:20px 80px 20px 0;min-width:40px;">
            <div class="flex-shrink-0" style="width:35px;height:35px;">
              <img src="<?= get_stylesheet_directory_uri(); ?>/assets/38ae819d53ac79772563328e97168cfba172d2b9.svg" alt="Tracking" style="width:100%;height:100%;object-fit:contain;">
            </div>
            <div class="flex-grow-1">
              <h4 class="m-0 mb-2" style="font-family:'elza',sans-serif;font-weight:500;font-size:18px;line-height:1;color:#003040;">More Than Just World-Leading Calibration</h4>
              <p class="m-0" style="font-family:'elza',sans-serif;font-weight:400;font-size:16px;line-height:1.4;color:#1C5263;">Go beyond basic tracking—IndySoft empowers you to manage, maintain, and optimize your assets with ease.</p>
            </div>
          </div>

