<!-- GSAP CDN -->
<script src="https://web-assets-acwebdev.s3.amazonaws.com/gsap/minified/gsap.min.js"></script>
<script src="https://web-assets-acwebdev.s3.amazonaws.com/gsap/minified/ScrollTrigger.min.js"></script>
<script src="https://web-assets-acwebdev.s3.amazonaws.com/gsap/minified/Flip.min.js"></script>

<!-- Swiper JS -->
<script src="https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.js"></script>

<!-- Swiper Initialization -->
<script>
document.addEventListener('DOMContentLoaded', function() {
  const swiper = new Swiper('.integrationsSwiper', {
    slidesPerView: 3,
    spaceBetween: 30,
    centeredSlides: true,
    initialSlide: 1, // Start with Calibration in centers
    loop: true,
    effect: 'slide',
    speed: 600,
    
    // Responsive breakpoints
    breakpoints: {
      320: {
        slidesPerView: 1,
        spaceBetween: 20
      },
      768: {
        slidesPerView: 2,  
        spaceBetween: 25
      },
      1024: {
        slidesPerView: 3,
        spaceBetween: 30
      }
    },

    // Navigation
    navigation: {
      nextEl: '.swiper-button-next-custom',
      prevEl: '.swiper-button-prev-custom',
    },

    // Events
    on: {
      slideChange: function () {
        updateSlideStyles();
      },
      init: function () {
        updateSlideStyles();
      }
    }
  });

  function updateSlideStyles() {
    const slides = document.querySelectorAll('.integrationsSwiper .swiper-slide');
    
    slides.forEach((slide, index) => {
      const isActive = slide.classList.contains('swiper-slide-active');
      
      if (isActive) {
        // Active (center) slide
        slide.style.transform = 'scale(1)';
        slide.style.opacity = '1';
        slide.style.zIndex = '10';
      } else {
        // Side slides
        slide.style.transform = 'scale(0.85)';
        slide.style.opacity = '0.7';
        slide.style.zIndex = '5';
      }
    });
  }

  // Hover effects
  const slides = document.querySelectorAll('.integrationsSwiper .swiper-slide');
  slides.forEach(slide => {
    slide.addEventListener('mouseenter', function() {
      if (!this.classList.contains('swiper-slide-active')) {
        this.style.transform = 'scale(0.9)';
      }
    });
    
    slide.addEventListener('mouseleave', function() {
      updateSlideStyles();
    });
  });

  // Initialize Testimonials Swiper
  const testimonialsSwiper = new Swiper('.testimonialsSwiper', {
    slidesPerView: 1,
    spaceBetween: 30,
    centeredSlides: true,
    loop: true,
    effect: 'slide',
    speed: 600,
    autoplay: {
      delay: 5000,
      disableOnInteraction: false,
    },

    // Navigation
    navigation: {
      nextEl: '.swiper-button-next-testimonials',
      prevEl: '.swiper-button-prev-testimonials',
    },

    // Responsive breakpoints
    breakpoints: {
      320: {
        slidesPerView: 1,
        spaceBetween: 20
      },
      768: {
        slidesPerView: 1,
        spaceBetween: 30
      },
      1024: {
        slidesPerView: 1,
        spaceBetween: 30
      }
    }
  });

  // Initialize Precision Swiper
  const precisionSwiper = new Swiper('.precisionSwiper', {
    slidesPerView: 3,
    spaceBetween: 30,
    centeredSlides: true,
    initialSlide: 1, // Start with Calibration in center (Tooling=0, Calibration=1, Maintenance=2)
    loop: false, // Temporarily disable loop to ensure proper initial slide
    effect: 'slide',
    speed: 800, // Increased to match CSS animation timing

    // Navigation
    navigation: {
      nextEl: '.swiper-button-next-precision',
      prevEl: '.swiper-button-prev-precision',
    },

    // Responsive breakpoints
    breakpoints: {
      320: {
        slidesPerView: 1,
        spaceBetween: 20,
        centeredSlides: true
      },
      768: {
        slidesPerView: 2,
        spaceBetween: 25,
        centeredSlides: true
      },
      1024: {
        slidesPerView: 3,
        spaceBetween: 30,
        centeredSlides: true
      }
    },

    // Events - CSS handles styling now, so minimal JS needed
    on: {
      slideChange: function () {
        // Let CSS handle the styling transitions
      },
      init: function () {
        // Ensure calibration slide (index 1) is active on initialization
        this.slideTo(1, 0); // Move to slide 1 (Calibration) immediately
        console.log('Precision swiper initialized on Calibration slide');
      }
    }
  });

  // Clean initialization - CSS handles all styling and animations
  document.addEventListener('DOMContentLoaded', function() {
    // Let CSS handle all styling - no JavaScript overrides needed
    console.log('Precision carousel initialized with CSS-driven animations');
  });

  // GSAP Smooth Countup Animation
  gsap.registerPlugin(ScrollTrigger, Flip);

  const buildReel = d => {
    const col = document.createElement('span');
    Object.assign(col.style, {
      display: 'inline-block',
      overflow: 'hidden',
      height: '1em',
      opacity: 0 // Start invisible
    });
    col.dataset.digit = d;

    const inner = document.createElement('div');
    inner.className = 'slot-inner';
    inner.style.willChange = 'transform';

    for (let i = 0; i < 20; i++) {
      const row = document.createElement('div');
      row.textContent = i % 10;
      Object.assign(row.style, {
        display: 'block',
        lineHeight: '1em'
      });
      inner.appendChild(row);
    }

    col.appendChild(inner);
    return col;
  };

  const countupElements = document.querySelectorAll('.countup-smooth');

  countupElements.forEach((el, elIndex) => {
    if (el.dataset.init) return;
    el.dataset.init = 1;

    const val = parseInt(el.dataset.count.replace(/,/g, ''), 10) || 0;
    el.innerHTML = '';
    val.toLocaleString().split('').forEach(ch => {
      if (/\d/.test(ch)) {
        el.appendChild(buildReel(+ch));
      } else {
        const s = document.createElement('span');
        s.textContent = ch;
        s.style.opacity = 0; // also fade in commas etc.
        s.style.marginTop = '-20px'; // Raise commas up more
        el.appendChild(s);
      }
    });

    ScrollTrigger.create({
      trigger: el,
      start: 'top 75%',
      once: true,
      onEnter: () => {
        el.querySelectorAll('span').forEach((span, digitIndex) => {
          // Fade in digits/commas/etc.
          gsap.to(span, {
            opacity: 1,
            duration: 0.8,
            delay: (elIndex * 0.4) + (digitIndex * 0.08), // longer group stagger
            ease: 'power3.out'
          });

          // Animate rolling digits only
          const inner = span.querySelector('.slot-inner');
          if (inner) {
            const rowH = inner.children[0].offsetHeight || parseFloat(getComputedStyle(inner.children[0]).fontSize);
            const target = +span.dataset.digit;
            const travel = -(10 + target) * rowH;
            gsap.fromTo(inner, { y: 0 }, {
              y: travel,
              duration: 5,
              delay: (elIndex * 0.4) + (digitIndex * 0.08), // match fade-in delay
              ease: 'expo.out'
            });
          }
        });
      }
    });
  });

  ScrollTrigger.refresh();

  // Enhanced Page Scroll Animations with More Movement
  gsap.set(['.animate-fade', '.animate-fade-up', '.animate-fade-left', '.animate-fade-right', '.animate-fade-down', '.animate-stagger'], {
    opacity: 0,
    y: function(index, element) {
      if (element.classList.contains('animate-fade-up')) return 20;
      if (element.classList.contains('animate-fade-down')) return -20;
      if (element.classList.contains('animate-stagger')) return 15;
      return 0;
    },
    x: function(index, element) {
      if (element.classList.contains('animate-fade-left')) return 20;
      if (element.classList.contains('animate-fade-right')) return -20;
      return 0;
    }
  });

  // Simple fade animations
  ScrollTrigger.batch('.animate-fade', {
    onEnter: (elements) => {
      gsap.to(elements, {
        opacity: 1,
        duration: 1.2,
        stagger: 0.15,
        ease: 'power3.out'
      });
    },
    start: 'top 70%',
    once: true
  });

  // Fade up animations
  ScrollTrigger.batch('.animate-fade-up', {
    onEnter: (elements) => {
      gsap.to(elements, {
        opacity: 1,
        y: 0,
        duration: 1.2,
        stagger: 0.2,
        ease: 'power3.out'
      });
    },
    start: 'top 70%',
    once: true
  });

  // Fade left animations
  ScrollTrigger.batch('.animate-fade-left', {
    onEnter: (elements) => {
      gsap.to(elements, {
        opacity: 1,
        x: 0,
        duration: 1.2,
        stagger: 0.15,
        ease: 'power3.out'
      });
    },
    start: 'top 70%',
    once: true
  });

  // Fade right animations
  ScrollTrigger.batch('.animate-fade-right', {
    onEnter: (elements) => {
      gsap.to(elements, {
        opacity: 1,
        x: 0,
        duration: 1.2,
        stagger: 0.15,
        ease: 'power3.out'
      });
    },
    start: 'top 70%',
    once: true
  });

  // Staggered group animations
  ScrollTrigger.batch('.animate-stagger', {
    onEnter: (elements) => {
      gsap.to(elements, {
        opacity: 1,
        y: 0,
        duration: 1.2,
        stagger: 0.25,
        ease: 'power3.out'
      });
    },
    start: 'top 70%',
    once: true
  });

  // Fade down animations (new)
  ScrollTrigger.batch('.animate-fade-down', {
    onEnter: (elements) => {
      gsap.to(elements, {
        opacity: 1,
        y: 0,
        duration: 1.2,
        stagger: 0.15,
        ease: 'power3.out'
      });
    },
    start: 'top 70%',
    once: true
  });

  // Refresh ScrollTrigger after all animations are set up
  ScrollTrigger.refresh();
});
</script>

